/** A foreign dictionary generation cannot inherit a paired predicate-domain qualification. */
@Timeout(90)
class LmdbDeferredDomainForeignWriterTest {
	private static final SimpleValueFactory VF = SimpleValueFactory.getInstance();
	private static final IRI S = VF.createIRI("urn:foreign-domain:subject");
	private static final IRI P = VF.createIRI("urn:foreign-domain:predicate");
	private static final IRI O = VF.createIRI("urn:foreign-domain:object");
	private static final byte[] KEY = "test.foreign-domain.commit".getBytes(StandardCharsets.US_ASCII);
	private static final List<SailRepository> RETAINED_OPEN_STORES = new CopyOnWriteArrayList<>();

	@ParameterizedTest(name = "foreign dictionary writer={0}")
	@ValueSource(booleans = { false, true })
	void foreignDictionaryCommitWithdrawsFactsFromBothOldAndCurrentPairedViews(boolean foreign,
			@TempDir(cleanup = CleanupMode.NEVER) Path evidence) throws Exception {
		Path directory = evidence.resolve("store");
		LmdbStoreConfig config = new LmdbStoreConfig("spoc,posc").setInlineLiterals(false)
				.setSketchEstimatorEnabled(false).setFrontierEstimatorMode(FrontierEstimatorMode.OFF)
				.setPredicateGuaranteeIndexEnabled(true).setPredicateGuaranteeIndexAutoRebuild(true);
		LmdbStore store = new LmdbStore(directory.toFile(), config);
		SailRepository repository = new SailRepository(store);
		AtomicBoolean childSettled = new AtomicBoolean(true);
		try (AutoCloseable cleanup = () -> {
			if (!childSettled.get()) {
				RETAINED_OPEN_STORES.add(repository);
				throw new IllegalStateException("External writer did not settle; native store and fixture were retained");
			}
			repository.shutDown();
		}) {
			repository.init();
			LmdbTestUtil.awaitPostReadyInitialization(store, 30, TimeUnit.SECONDS);
			assertTrue(store.awaitIndexRebuild(30, TimeUnit.SECONDS));
			try (var connection = repository.getConnection()) {
				connection.begin();
				connection.add(S, P, O);
				connection.commit();
			}
			LmdbSailStore backing = store.getBackingStore();
			TripleStore triples = backing.getTripleStore();
			ValueStore values = (ValueStore) backing.getValueFactory();
			long predicate = values.getId(P);
			long object = values.getId(O);
			LmdbEstimatorRuntime runtime = assertInstanceOf(LmdbEvaluationStatistics.class,
					store.getSailStore().getEvaluationStatistics()).estimatorRuntime();
			try (LmdbSailStore.ReadView old = openView(backing)) {
				assertEquals(Optional.of(RdfTermDomain.IRI), known(runtime, triples, old, predicate),
						"the paired control must begin with a real qualified IRI domain");
				long before = values.lastTransactionId();
				if (foreign) {
					childSettled.set(false);
					runForeignWriter(directory, evidence, childSettled);
					assertTrue(values.lastTransactionId() > before, "the child must commit a new native generation");
				} else {
					assertEquals(before, values.lastTransactionId());
				}
				Optional<RdfTermDomain> oldAfter = known(runtime, triples, old, predicate);
				try (LmdbSailStore.ReadView current = openView(backing)) {
					Optional<RdfTermDomain> currentAfter = known(runtime, triples, current, predicate);
					assertAll("foreign generation authority is not borrowed by either read view",
							() -> assertEquals(!foreign, oldAfter.isPresent(), "old paired view"),
							() -> assertEquals(!foreign, currentAfter.isPresent(), "current paired view"),
							() -> assertTrue(containsObject(triples, old, predicate, object), "old row remains visible"),
							() -> assertTrue(containsObject(triples, current, predicate, object), "current row remains visible"));
				}
			}
		}
	}

	private static LmdbSailStore.ReadView openView(LmdbSailStore backing) {
		try (LmdbSailStore.DatasetAdmission admission = backing.beginDatasetAdmission(IsolationLevels.SNAPSHOT_READ, null)) {
			admission.view().requireDictionaryTermSnapshot();
			return admission.view().retain();
		}
	}

	private static Optional<RdfTermDomain> known(LmdbEstimatorRuntime runtime, TripleStore triples,
			LmdbSailStore.ReadView view, long predicate) throws Exception {
		try (TripleStore.PlanningReadPin ignored = runtime.pinPlanningReads(view.tripleTxn(), view.valueSnapshot())) {
			return triples.getKnownRdfTermDomain(predicate);
		}
	}

	private static boolean containsObject(TripleStore triples, LmdbSailStore.ReadView view, long predicate, long object)
			throws Exception {
		try (RecordIterator rows = triples.getTriples(view.tripleTxn(), -1, predicate, object, -1, true)) {
			return rows.next() != null;
		}
	}

	private static void runForeignWriter(Path directory, Path evidence, AtomicBoolean settled) throws Exception {
		Path tmp = evidence.resolve("child-tmp");
		Files.createDirectory(tmp);
		Path log = evidence.resolve("foreign-dictionary-writer.log");
		Process child = new ProcessBuilder(Path.of(System.getProperty("java.home"), "bin", "java").toString(),
				"--enable-native-access=ALL-UNNAMED", "-ea", "-Djava.io.tmpdir=" + tmp,
				"-cp", System.getProperty("java.class.path"), ForeignWriter.class.getName(), directory.toString())
						.redirectErrorStream(true).redirectOutput(log.toFile()).start();
		if (!child.waitFor(30, TimeUnit.SECONDS)) {
			throw new AssertionError("foreign writer did not settle; retained child and store: " + log);
		}
		settled.set(true);
		String output = Files.readString(log);
		assertEquals(0, child.exitValue(), () -> "foreign writer failed: " + output);
		assertTrue(output.contains("FOREIGN_DICTIONARY_COMMITTED"), "real native commit must be reached");
	}

	public static final class ForeignWriter {
		public static void main(String[] args) throws Exception {
			LmdbCompatibilityFixtures.nativePut(Path.of(args[0]), "gc_meta", KEY, new byte[] { 1 });
			System.out.println("FOREIGN_DICTIONARY_COMMITTED");
		}
	}
}
